    assert_eq!(s.err(set("q", json!({"DeadLetterQueue": "q", "MaxReceiveCount": 2}))), "InvalidParameterValue");
    assert_eq!(s.err(set("q", json!({"DeadLetterQueue": "f.fifo", "MaxReceiveCount": 2}))), "InvalidParameterValue");

