#[test]
fn zero_visibility_makes_the_message_visible_at_once_with_a_dead_handle() {
    let mut s = session_with(&[("q", json!({}))]);
    send(&mut s, "q", "a");
    let got = receive(&mut s, "q", json!({"VisibilityTimeout": 0}));
